from __future__ import annotations

import numpy as np
import pandas as pd
from scipy.signal import butter, filtfilt, lfilter

from hdutils import ComponentInputValidationException, parse_default_value

FILTER_TYPES = {"lowpass": "low", "highpass": "high"}


def parse_fixed_timedelta_string(value: str, input_name: str) -> pd.Timedelta:
    if not isinstance(value, str) or not value.strip():
        raise ComponentInputValidationException(
            f"{input_name} must be a fixed timedelta string like '10s', '5min', or '1h'",
            error_code="422",
            invalid_component_inputs=[input_name],
        )

    try:
        offset = pd.tseries.frequencies.to_offset(value)
    except ValueError as exc:
        raise ComponentInputValidationException(
            f"{input_name} must be a valid fixed timedelta string like '10s', '5min', or '1h'",
            error_code="422",
            invalid_component_inputs=[input_name],
        ) from exc

    try:
        nanos = offset.nanos
    except ValueError as exc:
        raise ComponentInputValidationException(
            f"{input_name} must be a fixed timedelta string like '10s', '5min', or '1h'",
            error_code="422",
            invalid_component_inputs=[input_name],
        ) from exc

    if nanos <= 0:
        raise ComponentInputValidationException(
            f"{input_name} must be greater than zero",
            error_code="422",
            invalid_component_inputs=[input_name],
        )

    return pd.to_timedelta(nanos, unit="ns")


def prepare_series(timeseries: pd.Series) -> pd.Series:
    prepared = timeseries.sort_index()
    if not prepared.index.is_unique:
        prepared = prepared.groupby(level=0).mean()
    return prepared


def validate_inputs(
    timeseries: pd.Series,
    filter_type: str,
    cutoff_period: str,
    order: int,
    forward_backward: bool,
) -> pd.Timedelta:
    if not isinstance(timeseries, pd.Series):
        raise ComponentInputValidationException(
            "timeseries must be a pandas Series",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )
    if timeseries.empty or timeseries.size < 2:
        raise ComponentInputValidationException(
            "timeseries must contain at least two samples",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )
    if not pd.api.types.is_datetime64_any_dtype(timeseries.index):
        raise ComponentInputValidationException(
            "timeseries index must be datetime",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )
    if not pd.api.types.is_numeric_dtype(timeseries):
        raise ComponentInputValidationException(
            "timeseries values must be numeric",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )
    if filter_type not in FILTER_TYPES:
        raise ComponentInputValidationException(
            "filter_type must be one of 'lowpass' or 'highpass'",
            error_code="422",
            invalid_component_inputs=["filter_type"],
        )
    if not isinstance(order, int) or order < 1:
        raise ComponentInputValidationException(
            "order must be a positive integer",
            error_code="422",
            invalid_component_inputs=["order"],
        )
    if not isinstance(forward_backward, bool):
        raise ComponentInputValidationException(
            "forward_backward must be a boolean",
            error_code="422",
            invalid_component_inputs=["forward_backward"],
        )

    return parse_fixed_timedelta_string(cutoff_period, "cutoff_period")


def validate_prepared_series(
    prepared: pd.Series, cutoff_period: pd.Timedelta, order: int, forward_backward: bool
) -> float:
    if not np.isfinite(prepared.to_numpy(dtype=float)).all():
        raise ComponentInputValidationException(
            "timeseries must not contain NaN, inf, or -inf values",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )

    idx = prepared.index
    diffs_ns = (idx[1:] - idx[:-1]).astype("timedelta64[ns]").astype(np.int64)
    if (diffs_ns <= 0).any():
        raise ComponentInputValidationException(
            "timeseries index must be strictly increasing after duplicate timestamps are merged",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )
    if not np.all(diffs_ns == diffs_ns[0]):
        raise ComponentInputValidationException(
            "timeseries must have exactly constant spacing. Use resample_time_series upstream if needed",
            error_code="422",
            invalid_component_inputs=["timeseries"],
        )

    dt_seconds = float(diffs_ns[0]) / 1e9
    cutoff_seconds = cutoff_period.total_seconds()
    if cutoff_seconds <= 2 * dt_seconds:
        raise ComponentInputValidationException(
            "cutoff_period must be larger than two sampling intervals",
            error_code="422",
            invalid_component_inputs=["cutoff_period"],
        )

    if forward_backward:
        pad_length = 3 * (order + 1)
        if prepared.size <= pad_length:
            raise ComponentInputValidationException(
                f"timeseries must contain more than {pad_length} samples when forward_backward is True and order is {order}",
                error_code="422",
                invalid_component_inputs=["timeseries", "order", "forward_backward"],
            )

    nyquist_frequency = 0.5 / dt_seconds
    cutoff_frequency = 1.0 / cutoff_seconds
    normal_frequency = cutoff_frequency / nyquist_frequency
    if not (0 < normal_frequency < 1):
        raise ComponentInputValidationException(
            "cutoff_period is not compatible with the sampling interval",
            error_code="422",
            invalid_component_inputs=["cutoff_period"],
        )

    return normal_frequency


