from hdutils import parse_default_value  # noqa: E402, F401


def main(
    *,
    timeseries,
    filter_type="lowpass",
    cutoff_period="4s",
    order=1,
    forward_backward=True,
):
    # entrypoint function for this component
    # ***** DO NOT EDIT LINES ABOVE *****
    cutoff_period = validate_inputs(
        timeseries,
        filter_type,
        cutoff_period,
        order,
        forward_backward,
    )

    prepared = prepare_series(timeseries)
    normal_frequency = validate_prepared_series(prepared, cutoff_period, order, forward_backward)

    b, a = butter(order, normal_frequency, btype=FILTER_TYPES[filter_type], analog=False)
    values = prepared.to_numpy(dtype=float)
    filtered_values = filtfilt(b, a, values) if forward_backward else lfilter(b, a, values)

    return {
        "filtered_timeseries": pd.Series(filtered_values, index=prepared.index),
    }


